BEGIN;
CREATE TYPE formula_state AS ENUM ('draft','verified','deprecated','blocked');
CREATE TABLE formula_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),formula_key text NOT NULL,version text NOT NULL,domain text NOT NULL,state formula_state NOT NULL DEFAULT 'draft',expression jsonb NOT NULL,input_contract jsonb NOT NULL,output_contract jsonb NOT NULL,rounding_policy jsonb NOT NULL DEFAULT '{}'::jsonb,source_id uuid NOT NULL REFERENCES data_sources(id),verified_at timestamptz,verified_by text,content_hash text NOT NULL,UNIQUE(formula_key,version));
CREATE TABLE formula_test_vectors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),formula_key text NOT NULL,formula_version text NOT NULL,label text NOT NULL,inputs jsonb NOT NULL,expected jsonb NOT NULL,tolerance jsonb NOT NULL DEFAULT '{}'::jsonb,source_id uuid REFERENCES data_sources(id),state verification_state NOT NULL DEFAULT 'unknown',FOREIGN KEY(formula_key,formula_version) REFERENCES formula_registry(formula_key,version));
CREATE TABLE canonicalization_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),data_snapshot_id uuid REFERENCES data_snapshots(id),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,status ingestion_status NOT NULL DEFAULT 'running',transform_version text NOT NULL,input_manifest jsonb NOT NULL,output_manifest jsonb,metrics jsonb NOT NULL DEFAULT '{}'::jsonb,error_message text);
CREATE TABLE entity_quarantine (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),canonicalization_run_id uuid NOT NULL REFERENCES canonicalization_runs(id) ON DELETE CASCADE,domain text NOT NULL,record_key text NOT NULL,reasons text[] NOT NULL,payload jsonb NOT NULL,material boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,UNIQUE(canonicalization_run_id,domain,record_key));
COMMIT;

